def algorithm(func, dim, lb, ub, budget, rng):
    x = np.random.uniform(lb, ub, size=(budget, dim))
    for i in range(budget-1):
        scores = func(x[i])
        weights = 1 / (scores + 1e-10)
        weights /= np.sum(weights)
        x_new = x[i] + np.dot(np.diag(1/np.std(x, axis=0)), np.random.normal(size=(dim,), loc=0, scale=1)) * rng.uniform(size=(dim,))
        scores_new = func(x_new)
        if scores_new < scores:
            weights *= 2
            weights /= np.sum(weights)
            x[(i+1):] += (x_new - x[i]) / np.sum(weights[:i+1])
    return np.clip(np.mean(x, axis=0), lb, ub)

def algorithm(func, dim, lb, ub, budget, rng):
    def get_candidates(dim, lb, ub, budget):
        return np.random.uniform(lb, ub, (budget, dim))

    def evaluate(x):
        return func(x)

    candidates = get_candidates(dim, lb, ub, budget)
    best_candidate = np.min(evaluate(candidates), axis=0)

    for t in range(1, budget):
        current_temperature = 5.0 / t
        new_candidate = np.copy(np.random.uniform(lb, ub, dim))
        new_candidate_eval = evaluate(new_candidate)

        if rng.random() < np.exp((new_candidate_eval - best_candidate) / current_temperature):
            best_candidate = new_candidate

        # Clip candidates to [lb, ub]
        candidates[t] = np.clip(candidates[t], lb, ub)

    return best_candidate

